'use strict';
(function () {
  const $ = id => document.getElementById(id);
  const { DEFAULTS, buildPayload, makeQr, toSvg } = CopeQR;
  const downloadButtons = ['download-png', 'download-svg', 'download-json', 'copy-json'];
  let current = null;
  let hashGeneration = 0;

  function setDefaults() {
    $('apk-url').value = DEFAULTS.apkUrl;
    $('checksum').value = DEFAULTS.sha256;
  }
  function clearOutput() {
    current = null;
    $('qr-image').replaceChildren();
    $('payload').textContent = '';
    $('qr-placeholder').hidden = false;
    $('qr-state').textContent = 'Changed';
    $('qr-state').classList.remove('ready');
    $('qr-status').textContent = 'Settings changed. Generate a new QR code.';
    $('copy-status').textContent = '';
    downloadButtons.forEach(id => $(id).disabled = true);
    $('error').hidden = true;
  }
  function showError(message) {
    $('error').textContent = message;
    $('error').hidden = false;
    $('qr-state').textContent = 'Check settings';
  }
  function generate() {
    clearOutput();
    try {
      const payload = buildPayload({
        apkUrl: $('apk-url').value,
        checksum: $('checksum').value,
        wifi: { enabled: $('include-wifi').checked, ssid: $('ssid').value,
          security: $('security').value, password: $('wifi-password').value, hidden: $('hidden-network').checked }
      });
      const { qr, text } = makeQr(payload);
      const svg = toSvg(qr);
      // SVG contains only numeric QR coordinates generated by toSvg, never user text.
      $('qr-image').innerHTML = svg;
      current = { payload, qr, svg, text };
      $('qr-placeholder').hidden = true;
      $('payload').textContent = JSON.stringify(payload, null, 2);
      $('qr-state').textContent = 'Ready to scan';
      $('qr-state').classList.add('ready');
      $('qr-status').textContent = `QR code ready.${$('include-wifi').checked ? ' Includes Wi-Fi details.' : ''}`;
      downloadButtons.forEach(id => $(id).disabled = false);
    } catch (error) { showError(error.message); }
  }
  function download(blob, name) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = name;
    document.body.append(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 10000);
  }
  $('settings-form').addEventListener('submit', event => event.preventDefault());
  $('settings-form').addEventListener('input', event => {
    if (event.target.id === 'checksum') {
      hashGeneration++;
      $('hash-status').textContent = 'Checksum entered manually. Ensure it matches the hosted APK.';
    }
    clearOutput();
  });
  $('include-wifi').addEventListener('change', () => {
    const enabled = $('include-wifi').checked;
    $('wifi-fields').hidden = !enabled;
    $('wifi-fields').disabled = !enabled;
    $('include-wifi').setAttribute('aria-expanded', String(enabled));
    clearOutput();
  });
  $('security').addEventListener('change', () => {
    $('password-field').hidden = $('security').value === 'NONE';
    clearOutput();
  });
  $('reset-apk').addEventListener('click', () => {
    hashGeneration++;
    setDefaults();
    $('apk-file').value = '';
    $('hash-status').textContent = 'Official release restored. Generate a new QR to apply it.';
    clearOutput();
  });
  $('apk-file').addEventListener('change', async () => {
    const file = $('apk-file').files[0];
    const generation = ++hashGeneration;
    clearOutput();
    if (!file) return;
    // Never leave the previous APK's checksum paired with a newly selected APK.
    $('checksum').value = '';
    $('hash-status').textContent = 'Calculating SHA-256 on your device…';
    try {
      if (!crypto.subtle) throw new Error('APK hashing requires HTTPS or localhost. You can paste the hash manually.');
      if (file.size > 128 * 1024 * 1024) throw new Error('Choose an APK smaller than 128 MiB, or paste its hash.');
      const digest = await crypto.subtle.digest('SHA-256', await file.arrayBuffer());
      if (generation !== hashGeneration) return;
      $('checksum').value = Array.from(new Uint8Array(digest), n => n.toString(16).padStart(2, '0')).join('');
      $('hash-status').textContent = `Calculated for ${file.name}. Set its public APK download URL, then generate.`;
    } catch (error) {
      if (generation !== hashGeneration) return;
      $('hash-status').textContent = error.message;
      showError(error.message);
    }
  });
  $('generate').addEventListener('click', generate);
  $('download-svg').addEventListener('click', () => {
    if (current) download(new Blob([current.svg], { type: 'image/svg+xml' }), 'testdpc-enrollment.svg');
  });
  $('download-json').addEventListener('click', () => {
    if (current) download(new Blob([JSON.stringify(current.payload, null, 2) + '\n'], { type: 'application/json' }), 'testdpc-enrollment.json');
  });
  $('download-png').addEventListener('click', () => {
    if (!current) return;
    const qr = current.qr;
    const scale = 10;
    const count = qr.getModuleCount();
    const canvas = document.createElement('canvas');
    canvas.width = canvas.height = (count + 8) * scale;
    const ctx = canvas.getContext('2d');
    ctx.fillStyle = '#fff'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#000';
    for (let row = 0; row < count; row++) for (let col = 0; col < count; col++) {
      if (qr.isDark(row, col)) ctx.fillRect((col + 4) * scale, (row + 4) * scale, scale, scale);
    }
    canvas.toBlob(blob => {
      if (blob) download(blob, 'testdpc-enrollment.png');
      else showError('PNG export failed. Try downloading the SVG.');
    }, 'image/png');
  });
  $('copy-json').addEventListener('click', async () => {
    if (!current) return;
    try {
      await navigator.clipboard.writeText(JSON.stringify(current.payload, null, 2));
      $('copy-status').textContent = 'JSON copied.';
    } catch { $('copy-status').textContent = 'Clipboard unavailable. Select the JSON above, or download it.'; }
  });
  setDefaults();
  generate();
})();
